import React, { useState } from "react";
import { motion } from "framer-motion";
import { Send } from "lucide-react";
import axios from "axios";

const Feedback = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: "",
  });
  const [loading, setLoading] = useState(false);
  const [responseMsg, setResponseMsg] = useState("");

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResponseMsg("");

    try {
      // Send feedback to backend
      await axios.post("http://localhost:8080/api/feedback", formData);
      setResponseMsg("✅ Feedback submitted successfully!");
      setFormData({ name: "", email: "", message: "" });
    } catch (err) {
      console.error(err);
      setResponseMsg("❌ Failed to submit feedback. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center bg-gradient-to-br from-gray-900 via-gray-800 to-black text-white px-6 py-12">
      <motion.div
        initial={{ opacity: 0, y: 60 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="bg-gray-800/60 backdrop-blur-xl shadow-2xl rounded-2xl p-10 w-full max-w-lg border border-gray-700"
      >
        <h1 className="text-3xl font-bold text-center text-blue-400 mb-6">
          We Value Your Feedback 💬
        </h1>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Name Field */}
          <div>
            <label className="block text-sm font-semibold mb-2">Your Name</label>
            <input
              type="text"
              name="name"
              required
              value={formData.name}
              onChange={handleChange}
              className="w-full px-4 py-2 rounded-md bg-gray-900 border border-gray-600 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-blue-500 transition"
              placeholder="John Doe"
            />
          </div>

          {/* Email Field */}
          <div>
            <label className="block text-sm font-semibold mb-2">Email</label>
            <input
              type="email"
              name="email"
              required
              value={formData.email}
              onChange={handleChange}
              className="w-full px-4 py-2 rounded-md bg-gray-900 border border-gray-600 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-blue-500 transition"
              placeholder="you@example.com"
            />
          </div>

          {/* Message Field */}
          <div>
            <label className="block text-sm font-semibold mb-2">Message</label>
            <textarea
              name="message"
              rows="4"
              required
              value={formData.message}
              onChange={handleChange}
              className="w-full px-4 py-2 rounded-md bg-gray-900 border border-gray-600 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-blue-500 transition resize-none"
              placeholder="Share your thoughts..."
            ></textarea>
          </div>

          {/* Submit Button */}
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            type="submit"
            disabled={loading}
            className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 transition text-white font-semibold py-2.5 rounded-lg shadow-lg"
          >
            {loading ? "Submitting..." : "Submit Feedback"}
            {!loading && <Send className="w-5 h-5" />}
          </motion.button>
        </form>

        {/* Response Message */}
        {responseMsg && (
          <p
            className={`text-center mt-5 font-medium ${
              responseMsg.includes("✅")
                ? "text-green-400"
                : "text-red-400"
            }`}
          >
            {responseMsg}
          </p>
        )}
      </motion.div>
    </div>
  );
};

export default Feedback;
